return [{
  json: {
    products: [
      {
        title: "Test 3D Model",
        description: "This is a cool test model for 3D printing.",
        images: ["https://makerworld.bblmw.com/makerworld/model/US384cf224c6e932/design/2024-04-12_2738a0f9b6b90.jpg"]
      }
    ]
  }
}];

// Llama a Gemini API para enriquecer los productos
const products = $input.all()[0].json.products;

// Reemplaza esto con tu API Key real de Google Gemini
const GEMINI_API_KEY = "TU_API_KEY_AQUI"; 
const GEMINI_URL = "https://generativelanguage.googleapis.com/v1beta/models/gemini-3-flash-preview:generateContent?key=" + GEMINI_API_KEY.trim();


    let cookieString = "";
    try {
        const cookies = $("MakerWorld: search").first().json.solution.cookies || [];
        cookieString = cookies.map(c => `${c.name}=${c.value}`).join("; ");
    } catch(e) {}

for (let i = 0; i < products.length; i++) {
    const p = products[i];
    if (!p.title) continue;
    if (GEMINI_API_KEY.includes("TU_API_KEY_AQUI") || GEMINI_API_KEY.trim() === "") {
        p.description = "ERROR: OLVIDASTE PONER TU API KEY DE GEMINI EN EL NODO DE CODIGO!";
        continue;
    }

    let base64Image = null;
    try {
        let mimeType = "image/jpeg";
        const imgUrl = (p.images && p.images.length > 0) ? p.images[0] : p.imageUrl;

        if (imgUrl) {
            try {
                const imgBuffer = await this.helpers.httpRequest({
                    method: "GET",
                    url: imgUrl,
                    encoding: null,
                    responseType: "arraybuffer",
                    timeout: 5000
                });
                if (imgBuffer) {
                    base64Image = Buffer.from(imgBuffer).toString("base64");
                    if (imgUrl.toLowerCase().includes(".png")) mimeType = "image/png";
                    else if (imgUrl.toLowerCase().includes(".webp")) mimeType = "image/webp";
                }
            } catch (imgErr) {
                console.log("Error descargando imagen:", imgErr.message);
            }
        }

        await new Promise(r => setTimeout(r, 2000));
        const prompt = `Analiza el siguiente producto de impresión 3D:
Título: ${p.title}
Descripción actual: ${p.description?.slice(0, 500)}

${base64Image ? 'También te he adjuntado una imagen del producto para que la analices.' : ''}

Devuelve un JSON válido con esta estructura exacta:
{
  "description": "Una descripción corta y atractiva para marketing (max 150 caracteres) basada en el texto y la imagen",
  "category": "Elige una de: Herramientas, Juguetes, Electrónica, Decoración, Gadgets, Impresión 3D",
  "hashtags": ["tag1", "tag2", "tag3"]
}`;

        const parts = [{ text: prompt }];
        if (base64Image) {
            parts.push({
                inlineData: {
                    mimeType: mimeType,
                    data: base64Image
                }
            });
        }

        const response = await this.helpers.httpRequest({
            method: "POST",
            url: GEMINI_URL,
            headers: { "Content-Type": "application/json" },
            body: { contents: [{ parts }] }
        });

        const rawText = response?.candidates?.[0]?.content?.parts?.[0]?.text || "";
        try {
            const jsonMatch = rawText.match(/\{.*\}/s);
            if (jsonMatch) {
                const aiData = JSON.parse(jsonMatch[0]);
                p.description = aiData.description;
                p.category = aiData.category;
                p.tags = aiData.hashtags;
                p.RAW_GEMINI_OUTPUT = rawText; // para ver que respondio
            } else {
                p.description = "DEBUG GEMINI (NO JSON): " + rawText.slice(0, 300);
            }
        } catch (parseErr) {
            p.description = "DEBUG GEMINI (JSON INVALIDO): " + parseErr.message;
        }
    } catch (e) {
        let errStr = e.message || e.toString();
        if (e.error) errStr += " | " + JSON.stringify(e.error);
        p.description = "DEBUG GEMINI (ERROR CONEXION): " + errStr;
    }
}

return [{ json: { products } }];
